SELECT store_id, CASE WHEN quantity >= 180 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(quantity), 2) AS avg_quantity, COUNT(DISTINCT id) AS distinct_ids_2, BIT_OR(quantity) AS quantity_bit_or FROM inventory GROUP BY CUBE (store_id, CASE WHEN quantity >= 180 THEN 'LARGE' ELSE 'SMALL' END) HAVING COUNT(DISTINCT id) < 1000 ORDER BY distinct_ids DESC NULLS FIRST;
